export const installFiles:Record<string,Record<string,string>> = {"sto-booking": {"README.md": "# BotStore — STO Booking\n\nҚАЗАҚША\n1. Python 3.10+ орнатыңыз. ZIP архивін жеке папкаға ашыңыз.\n2. Telegram @BotFather арқылы жаңа бот ашыңыз.\n3. Windows: start.bat. macOS/Linux: bash start.sh. Токенді тек өз компьютеріңізде енгізіңіз.\n4. Ботқа /id жазыңыз. Өз нөміріңізді config.json ішіндегі adminChatId өрісіне немесе сайттағы орнату шеберіне қосыңыз. Қайта іске қосыңыз.\n5. Клиент /start → қызмет → күн → бос уақыт → көлік пен телефон жазады. /my немесе /cancel арқылы жазылуды басқарады.\n6. Компьютер/сервер үнемі қосулы болуы керек. Хостинг және төлем қабылдау кірмейді. Бір слотқа бір көлік, уақыт белдеуі UTC+5. Алдағы 7 күн көрсетіледі. Қызметтер ұзақтығын слоттарды таңдағанда ескеріңіз.\n\nРУССКИЙ\n1. Установите Python 3.10+, распакуйте ZIP.\n2. Создайте нового бота через @BotFather.\n3. Запустите start.bat (Windows) или bash start.sh (macOS/Linux). Введите токен на своём компьютере. BotStore не сохраняет токен.\n4. Отправьте /id своему боту. Укажите полученный ID в adminChatId в config.json или мастере настройки, перезапустите.\n5. Клиент выбирает услугу, день и слот, вводит автомобиль и телефон. /my и /cancel показывают записи и отмену. Одновременно слот бронируется только один раз.\n6. Компьютер или сервер должен работать постоянно. Хостинг и приём платежей не включены. Часовой пояс UTC+5, расписание на 7 дней, одна машина на слот. Задайте интервалы с учётом длительности работ.\n\nENGLISH\n1. Install Python 3.10+ and extract ZIP.\n2. Create a new bot with @BotFather.\n3. Run start.bat (Windows) or bash start.sh (macOS/Linux). Enter the token locally; BotStore never stores it.\n4. Send /id to your bot. Add the result as adminChatId in config.json or in the setup wizard. Restart.\n5. Customer flow: /start → service → day → available slot → vehicle and phone. /my and /cancel allow viewing/cancelling bookings.\n6. An always-running computer/server is required. Hosting and payments are not included. UTC+5, next 7 days, one vehicle per slot. Space slots to accommodate your service duration.\n\nData is stored locally in bookings.sqlite3. Back up this file privately. Do not share it with customers or commit it to a public repository. Do not run two bot instances at once. MIT license; provided as-is without warranty.\n", "bot.py": "\"\"\"BotStore appointment bot. Python 3.10+. One booking per time slot, UTC+5.\"\"\"\nimport json,os,time,sqlite3,urllib.request,logging\nfrom datetime import datetime,timedelta,timezone\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parent\nCONFIG=json.loads((ROOT/'config.json').read_text(encoding='utf-8'))\nTOKEN=os.environ.get('BOT_TOKEN','')\nADMIN=CONFIG.get('adminChatId','')\nTZ=timezone(timedelta(hours=5))\nLANG=CONFIG.get('language','kk')\nTEXTS={\n'kk':dict(welcome='Сәлем! Қызметті таңдаңыз:',date='Күнді таңдаңыз:',time='Бос уақытты таңдаңыз:',phone='Көлік маркасын және байланыс телефоныңызды жазыңыз:',done='Жазылу расталды',busy='Бұл уақыт бос емес. /start арқылы басқа уақытты таңдаңыз.',invalid='Қайта бастау үшін /start басыңыз.',mine='Сіздің жазылуларыңыз:',cancel='Жазылуды болдырмау',cancelled='Жазылу тоқтатылды.',none='Белсенді жазылу жоқ.',contact='Телефон мен көлік туралы ақпаратты жазыңыз (8–150 таңба).'),\n'ru':dict(welcome='Здравствуйте! Выберите услугу:',date='Выберите день:',time='Выберите свободное время:',phone='Напишите марку машины и контактный телефон:',done='Запись подтверждена',busy='Это время уже занято. Выберите другое через /start.',invalid='Начните заново: /start',mine='Ваши записи:',cancel='Отменить запись',cancelled='Запись отменена.',none='Нет активных записей.',contact='Укажите телефон и автомобиль (8–150 символов).'),\n'en':dict(welcome='Welcome! Choose a service:',date='Choose a date:',time='Choose an available time:',phone='Send your vehicle model and contact phone number:',done='Booking confirmed',busy='This time is no longer available. Choose another with /start.',invalid='Start again: /start',mine='Your bookings:',cancel='Cancel booking',cancelled='Booking cancelled.',none='No active bookings.',contact='Enter a phone number and vehicle (8–150 characters).')}\nT=TEXTS.get(LANG,TEXTS['kk']).copy()\nif CONFIG.get('sector') in ('salon','studio'):\n T['phone']={'kk':'Атыңызды және байланыс телефоныңызды жазыңыз:','ru':'Напишите имя и контактный телефон:','en':'Send your name and contact phone number:'}.get(LANG,'Send your name and phone number:')\n T['contact']={'kk':'Атыңыз бен телефоныңызды жазыңыз (8–150 таңба).','ru':'Укажите имя и телефон (8–150 символов).','en':'Enter your name and phone (8–150 characters).'}.get(LANG,'Enter your name and phone.')\nDB=sqlite3.connect(ROOT/'bookings.sqlite3')\nDB.executescript('CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY,chat INTEGER NOT NULL,slot TEXT NOT NULL,service TEXT NOT NULL,contact TEXT NOT NULL,status TEXT NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS booked_slot ON bookings(slot) WHERE status=\"booked\"; CREATE TABLE IF NOT EXISTS sessions(chat INTEGER PRIMARY KEY,data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT);')\ndef api(method,data):\n req=urllib.request.Request('https://api.telegram.org/bot'+TOKEN+'/'+method,data=json.dumps(data).encode(),headers={'Content-Type':'application/json'})\n with urllib.request.urlopen(req,timeout=40) as r:res=json.load(r)\n if not res.get('ok'):raise RuntimeError('Telegram API error')\n return res['result']\ndef send(chat,text,buttons=None):\n data={'chat_id':chat,'text':text[:4000]}\n if buttons:data['reply_markup']={'inline_keyboard':buttons}\n return api('sendMessage',data)\ndef save(chat,data):\n DB.execute('INSERT INTO sessions(chat,data) VALUES(?,?) ON CONFLICT(chat) DO UPDATE SET data=excluded.data',(chat,json.dumps(data)));DB.commit()\ndef session(chat):\n row=DB.execute('SELECT data FROM sessions WHERE chat=?',(chat,)).fetchone();return json.loads(row[0]) if row else {}\ndef button(text,value):return {'text':text,'callback_data':value}\ndef start(chat):\n save(chat,{})\n send(chat,CONFIG['businessName']+'\\n'+T['welcome'],[[button(s['name']+' · '+str(s['price'])+' ₸','s:'+str(i))] for i,s in enumerate(CONFIG['services'])])\ndef mine(chat):\n rows=DB.execute('SELECT id,slot,service FROM bookings WHERE chat=? AND status=\"booked\" AND slot>? ORDER BY slot',(chat,datetime.now(TZ).strftime('%Y-%m-%d %H:%M'))).fetchall()\n if not rows:send(chat,T['none']);return\n for id,slot,service in rows:send(chat,service+'\\n'+slot,[[button(T['cancel'],'c:'+str(id))]])\ndef handle(update):\n q=update.get('callback_query')\n if q:\n  if q.get('message',{}).get('chat',{}).get('type')!='private':return\n  chat=q['from']['id'];value=q.get('data','');api('answerCallbackQuery',{'callback_query_id':q['id']});state=session(chat)\n  if value.startswith('c:'):\n   try:id=int(value[2:])\n   except ValueError:return\n   row=DB.execute('SELECT slot,service FROM bookings WHERE id=? AND chat=? AND status=\"booked\"',(id,chat)).fetchone()\n   DB.execute('UPDATE bookings SET status=\"cancelled\" WHERE id=? AND chat=?',(id,chat));DB.commit();send(chat,T['cancelled'])\n   if row and ADMIN:\n    try:send(ADMIN,'CANCELLED / ОТМЕНА / ТОҚТАТЫЛДЫ\\n'+row[0]+'\\n'+row[1])\n    except Exception:logging.warning('Admin notification failed')\n   return\n  if value.startswith('s:'):\n   try:i=int(value[2:])\n   except ValueError:return\n   if i<0 or i>=len(CONFIG['services']):return\n   save(chat,{'service':i});send(chat,T['date'],[[button((datetime.now(TZ)+timedelta(days=d)).strftime('%d.%m'), 'd:'+(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d'))] for d in range(7)]);return\n  if value.startswith('d:') and 'service' in state:\n   day=value[2:];allowed={(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d') for d in range(7)}\n   if day not in allowed:send(chat,T['invalid']);return\n   state['day']=day;state.pop('slot',None);save(chat,state);used={r[0] for r in DB.execute('SELECT slot FROM bookings WHERE status=\"booked\"').fetchall()};slots=[h for h in CONFIG['hours'] if day+' '+h not in used and day+' '+h>datetime.now(TZ).strftime('%Y-%m-%d %H:%M')]\n   send(chat,T['time'] if slots else T['busy'],[[button(h,'t:'+h)] for h in slots] if slots else None);return\n  if value.startswith('t:') and 'day' in state and 'service' in state:\n   hour=value[2:]\n   if hour not in CONFIG['hours']:return\n   state['slot']=state['day']+' '+hour;save(chat,state);send(chat,T['phone']);return\n  send(chat,T['invalid']);return\n msg=update.get('message',{})\n if msg.get('chat',{}).get('type')!='private':return\n chat=msg['chat']['id'];text=msg.get('text','').strip()\n if text=='/id':send(chat,str(chat));return\n if text.startswith('/start'):start(chat);return\n if text in ['/my','/cancel']:mine(chat);return\n state=session(chat)\n if 'slot' not in state:send(chat,T['invalid']);return\n if len(text)<8 or len(text)>150 or sum(c.isdigit() for c in text)<7:send(chat,T['contact']);return\n if state['slot']<=datetime.now(TZ).strftime('%Y-%m-%d %H:%M'):send(chat,T['busy']);return\n service=CONFIG['services'][state['service']];id=update['update_id']\n try:\n  DB.execute('INSERT INTO bookings(id,chat,slot,service,contact,status) VALUES(?,?,?,?,?,\"booked\")',(id,chat,state['slot'],service['name'],text));DB.commit()\n except sqlite3.IntegrityError:\n  existing=DB.execute('SELECT id FROM bookings WHERE id=? AND chat=?',(id,chat)).fetchone()\n  if not existing:send(chat,T['busy']);return\n save(chat,{})\n send(chat,T['done']+' ✓\\n'+service['name']+' · '+str(service['price'])+' ₸\\n'+state['slot']+' (UTC+5)',[[button(T['cancel'],'c:'+str(id))]])\n if ADMIN:\n  try:send(ADMIN,'NEW BOOKING / НОВАЯ ЗАПИСЬ / ЖАҢА ЖАЗЫЛУ\\n'+state['slot']+'\\n'+service['name']+'\\n'+text)\n  except Exception:logging.warning('Admin notification failed: check ADMIN chat has started the bot')\ndef main():\n if not TOKEN:raise SystemExit('Set BOT_TOKEN or use start.bat / start.sh')\n api('getMe',{});webhook=api('getWebhookInfo',{})\n if webhook.get('url'):raise SystemExit('This bot has a webhook. Use a new bot or remove the previous webhook intentionally before polling.')\n row=DB.execute('SELECT value FROM meta WHERE key=\"offset\"').fetchone();offset=int(row[0]) if row else 0\n print('BotStore booking bot running. Ctrl+C to stop.')\n while True:\n  try:\n   for update in api('getUpdates',{'offset':offset,'timeout':25,'allowed_updates':['message','callback_query']}):\n    try:handle(update)\n    except Exception:logging.warning('Update processing failed. Check connectivity and configuration.')\n    offset=update['update_id']+1;DB.execute('INSERT INTO meta(key,value) VALUES(\"offset\",?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(str(offset),));DB.commit()\n  except KeyboardInterrupt:break\n  except Exception:logging.warning('Connection unavailable, retrying');time.sleep(5)\nif __name__=='__main__':main()\n", "config.json": "{\"businessName\":\"My Service\",\"language\":\"kk\",\"adminChatId\":\"\",\"services\":[{\"name\":\"Диагностика\",\"price\":5000},{\"name\":\"Май ауыстыру / Замена масла\",\"price\":7500}],\"hours\":[\"09:00\",\"10:00\",\"11:00\",\"14:00\",\"15:00\",\"16:00\"]}\n", "start.bat": "@echo off\ncd /d \"%~dp0\"\nset /p BOT_TOKEN=Telegram bot token (do not share): \npython bot.py\npause\n", "start.sh": "#!/usr/bin/env bash\ncd -- \"$(dirname -- \"$0\")\"\nread -r -s -p 'Telegram bot token (do not share): ' BOT_TOKEN\nprintf '\\n'\nexport BOT_TOKEN\npython3 bot.py\n"}, "pack-sto": {"sto-booking/README.md": "# BotStore — STO Booking\n\nҚАЗАҚША\n1. Python 3.10+ орнатыңыз. ZIP архивін жеке папкаға ашыңыз.\n2. Telegram @BotFather арқылы жаңа бот ашыңыз.\n3. Windows: start.bat. macOS/Linux: bash start.sh. Токенді тек өз компьютеріңізде енгізіңіз.\n4. Ботқа /id жазыңыз. Өз нөміріңізді config.json ішіндегі adminChatId өрісіне немесе сайттағы орнату шеберіне қосыңыз. Қайта іске қосыңыз.\n5. Клиент /start → қызмет → күн → бос уақыт → көлік пен телефон жазады. /my немесе /cancel арқылы жазылуды басқарады.\n6. Компьютер/сервер үнемі қосулы болуы керек. Хостинг және төлем қабылдау кірмейді. Бір слотқа бір көлік, уақыт белдеуі UTC+5. Алдағы 7 күн көрсетіледі. Қызметтер ұзақтығын слоттарды таңдағанда ескеріңіз.\n\nРУССКИЙ\n1. Установите Python 3.10+, распакуйте ZIP.\n2. Создайте нового бота через @BotFather.\n3. Запустите start.bat (Windows) или bash start.sh (macOS/Linux). Введите токен на своём компьютере. BotStore не сохраняет токен.\n4. Отправьте /id своему боту. Укажите полученный ID в adminChatId в config.json или мастере настройки, перезапустите.\n5. Клиент выбирает услугу, день и слот, вводит автомобиль и телефон. /my и /cancel показывают записи и отмену. Одновременно слот бронируется только один раз.\n6. Компьютер или сервер должен работать постоянно. Хостинг и приём платежей не включены. Часовой пояс UTC+5, расписание на 7 дней, одна машина на слот. Задайте интервалы с учётом длительности работ.\n\nENGLISH\n1. Install Python 3.10+ and extract ZIP.\n2. Create a new bot with @BotFather.\n3. Run start.bat (Windows) or bash start.sh (macOS/Linux). Enter the token locally; BotStore never stores it.\n4. Send /id to your bot. Add the result as adminChatId in config.json or in the setup wizard. Restart.\n5. Customer flow: /start → service → day → available slot → vehicle and phone. /my and /cancel allow viewing/cancelling bookings.\n6. An always-running computer/server is required. Hosting and payments are not included. UTC+5, next 7 days, one vehicle per slot. Space slots to accommodate your service duration.\n\nData is stored locally in bookings.sqlite3. Back up this file privately. Do not share it with customers or commit it to a public repository. Do not run two bot instances at once. MIT license; provided as-is without warranty.\n", "sto-booking/bot.py": "\"\"\"BotStore appointment bot. Python 3.10+. One booking per time slot, UTC+5.\"\"\"\nimport json,os,time,sqlite3,urllib.request,logging\nfrom datetime import datetime,timedelta,timezone\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parent\nCONFIG=json.loads((ROOT/'config.json').read_text(encoding='utf-8'))\nTOKEN=os.environ.get('BOT_TOKEN','')\nADMIN=CONFIG.get('adminChatId','')\nTZ=timezone(timedelta(hours=5))\nLANG=CONFIG.get('language','kk')\nTEXTS={\n'kk':dict(welcome='Сәлем! Қызметті таңдаңыз:',date='Күнді таңдаңыз:',time='Бос уақытты таңдаңыз:',phone='Көлік маркасын және байланыс телефоныңызды жазыңыз:',done='Жазылу расталды',busy='Бұл уақыт бос емес. /start арқылы басқа уақытты таңдаңыз.',invalid='Қайта бастау үшін /start басыңыз.',mine='Сіздің жазылуларыңыз:',cancel='Жазылуды болдырмау',cancelled='Жазылу тоқтатылды.',none='Белсенді жазылу жоқ.',contact='Телефон мен көлік туралы ақпаратты жазыңыз (8–150 таңба).'),\n'ru':dict(welcome='Здравствуйте! Выберите услугу:',date='Выберите день:',time='Выберите свободное время:',phone='Напишите марку машины и контактный телефон:',done='Запись подтверждена',busy='Это время уже занято. Выберите другое через /start.',invalid='Начните заново: /start',mine='Ваши записи:',cancel='Отменить запись',cancelled='Запись отменена.',none='Нет активных записей.',contact='Укажите телефон и автомобиль (8–150 символов).'),\n'en':dict(welcome='Welcome! Choose a service:',date='Choose a date:',time='Choose an available time:',phone='Send your vehicle model and contact phone number:',done='Booking confirmed',busy='This time is no longer available. Choose another with /start.',invalid='Start again: /start',mine='Your bookings:',cancel='Cancel booking',cancelled='Booking cancelled.',none='No active bookings.',contact='Enter a phone number and vehicle (8–150 characters).')}\nT=TEXTS.get(LANG,TEXTS['kk']).copy()\nif CONFIG.get('sector') in ('salon','studio'):\n T['phone']={'kk':'Атыңызды және байланыс телефоныңызды жазыңыз:','ru':'Напишите имя и контактный телефон:','en':'Send your name and contact phone number:'}.get(LANG,'Send your name and phone number:')\n T['contact']={'kk':'Атыңыз бен телефоныңызды жазыңыз (8–150 таңба).','ru':'Укажите имя и телефон (8–150 символов).','en':'Enter your name and phone (8–150 characters).'}.get(LANG,'Enter your name and phone.')\nDB=sqlite3.connect(ROOT/'bookings.sqlite3')\nDB.executescript('CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY,chat INTEGER NOT NULL,slot TEXT NOT NULL,service TEXT NOT NULL,contact TEXT NOT NULL,status TEXT NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS booked_slot ON bookings(slot) WHERE status=\"booked\"; CREATE TABLE IF NOT EXISTS sessions(chat INTEGER PRIMARY KEY,data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT);')\ndef api(method,data):\n req=urllib.request.Request('https://api.telegram.org/bot'+TOKEN+'/'+method,data=json.dumps(data).encode(),headers={'Content-Type':'application/json'})\n with urllib.request.urlopen(req,timeout=40) as r:res=json.load(r)\n if not res.get('ok'):raise RuntimeError('Telegram API error')\n return res['result']\ndef send(chat,text,buttons=None):\n data={'chat_id':chat,'text':text[:4000]}\n if buttons:data['reply_markup']={'inline_keyboard':buttons}\n return api('sendMessage',data)\ndef save(chat,data):\n DB.execute('INSERT INTO sessions(chat,data) VALUES(?,?) ON CONFLICT(chat) DO UPDATE SET data=excluded.data',(chat,json.dumps(data)));DB.commit()\ndef session(chat):\n row=DB.execute('SELECT data FROM sessions WHERE chat=?',(chat,)).fetchone();return json.loads(row[0]) if row else {}\ndef button(text,value):return {'text':text,'callback_data':value}\ndef start(chat):\n save(chat,{})\n send(chat,CONFIG['businessName']+'\\n'+T['welcome'],[[button(s['name']+' · '+str(s['price'])+' ₸','s:'+str(i))] for i,s in enumerate(CONFIG['services'])])\ndef mine(chat):\n rows=DB.execute('SELECT id,slot,service FROM bookings WHERE chat=? AND status=\"booked\" AND slot>? ORDER BY slot',(chat,datetime.now(TZ).strftime('%Y-%m-%d %H:%M'))).fetchall()\n if not rows:send(chat,T['none']);return\n for id,slot,service in rows:send(chat,service+'\\n'+slot,[[button(T['cancel'],'c:'+str(id))]])\ndef handle(update):\n q=update.get('callback_query')\n if q:\n  if q.get('message',{}).get('chat',{}).get('type')!='private':return\n  chat=q['from']['id'];value=q.get('data','');api('answerCallbackQuery',{'callback_query_id':q['id']});state=session(chat)\n  if value.startswith('c:'):\n   try:id=int(value[2:])\n   except ValueError:return\n   row=DB.execute('SELECT slot,service FROM bookings WHERE id=? AND chat=? AND status=\"booked\"',(id,chat)).fetchone()\n   DB.execute('UPDATE bookings SET status=\"cancelled\" WHERE id=? AND chat=?',(id,chat));DB.commit();send(chat,T['cancelled'])\n   if row and ADMIN:\n    try:send(ADMIN,'CANCELLED / ОТМЕНА / ТОҚТАТЫЛДЫ\\n'+row[0]+'\\n'+row[1])\n    except Exception:logging.warning('Admin notification failed')\n   return\n  if value.startswith('s:'):\n   try:i=int(value[2:])\n   except ValueError:return\n   if i<0 or i>=len(CONFIG['services']):return\n   save(chat,{'service':i});send(chat,T['date'],[[button((datetime.now(TZ)+timedelta(days=d)).strftime('%d.%m'), 'd:'+(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d'))] for d in range(7)]);return\n  if value.startswith('d:') and 'service' in state:\n   day=value[2:];allowed={(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d') for d in range(7)}\n   if day not in allowed:send(chat,T['invalid']);return\n   state['day']=day;state.pop('slot',None);save(chat,state);used={r[0] for r in DB.execute('SELECT slot FROM bookings WHERE status=\"booked\"').fetchall()};slots=[h for h in CONFIG['hours'] if day+' '+h not in used and day+' '+h>datetime.now(TZ).strftime('%Y-%m-%d %H:%M')]\n   send(chat,T['time'] if slots else T['busy'],[[button(h,'t:'+h)] for h in slots] if slots else None);return\n  if value.startswith('t:') and 'day' in state and 'service' in state:\n   hour=value[2:]\n   if hour not in CONFIG['hours']:return\n   state['slot']=state['day']+' '+hour;save(chat,state);send(chat,T['phone']);return\n  send(chat,T['invalid']);return\n msg=update.get('message',{})\n if msg.get('chat',{}).get('type')!='private':return\n chat=msg['chat']['id'];text=msg.get('text','').strip()\n if text=='/id':send(chat,str(chat));return\n if text.startswith('/start'):start(chat);return\n if text in ['/my','/cancel']:mine(chat);return\n state=session(chat)\n if 'slot' not in state:send(chat,T['invalid']);return\n if len(text)<8 or len(text)>150 or sum(c.isdigit() for c in text)<7:send(chat,T['contact']);return\n if state['slot']<=datetime.now(TZ).strftime('%Y-%m-%d %H:%M'):send(chat,T['busy']);return\n service=CONFIG['services'][state['service']];id=update['update_id']\n try:\n  DB.execute('INSERT INTO bookings(id,chat,slot,service,contact,status) VALUES(?,?,?,?,?,\"booked\")',(id,chat,state['slot'],service['name'],text));DB.commit()\n except sqlite3.IntegrityError:\n  existing=DB.execute('SELECT id FROM bookings WHERE id=? AND chat=?',(id,chat)).fetchone()\n  if not existing:send(chat,T['busy']);return\n save(chat,{})\n send(chat,T['done']+' ✓\\n'+service['name']+' · '+str(service['price'])+' ₸\\n'+state['slot']+' (UTC+5)',[[button(T['cancel'],'c:'+str(id))]])\n if ADMIN:\n  try:send(ADMIN,'NEW BOOKING / НОВАЯ ЗАПИСЬ / ЖАҢА ЖАЗЫЛУ\\n'+state['slot']+'\\n'+service['name']+'\\n'+text)\n  except Exception:logging.warning('Admin notification failed: check ADMIN chat has started the bot')\ndef main():\n if not TOKEN:raise SystemExit('Set BOT_TOKEN or use start.bat / start.sh')\n api('getMe',{});webhook=api('getWebhookInfo',{})\n if webhook.get('url'):raise SystemExit('This bot has a webhook. Use a new bot or remove the previous webhook intentionally before polling.')\n row=DB.execute('SELECT value FROM meta WHERE key=\"offset\"').fetchone();offset=int(row[0]) if row else 0\n print('BotStore booking bot running. Ctrl+C to stop.')\n while True:\n  try:\n   for update in api('getUpdates',{'offset':offset,'timeout':25,'allowed_updates':['message','callback_query']}):\n    try:handle(update)\n    except Exception:logging.warning('Update processing failed. Check connectivity and configuration.')\n    offset=update['update_id']+1;DB.execute('INSERT INTO meta(key,value) VALUES(\"offset\",?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(str(offset),));DB.commit()\n  except KeyboardInterrupt:break\n  except Exception:logging.warning('Connection unavailable, retrying');time.sleep(5)\nif __name__=='__main__':main()\n", "sto-booking/config.json": "{\n  \"businessName\": \"My Service\",\n  \"language\": \"kk\",\n  \"adminChatId\": \"\",\n  \"services\": [\n    {\n      \"name\": \"Диагностика\",\n      \"price\": 5000\n    },\n    {\n      \"name\": \"Май ауыстыру / Замена масла\",\n      \"price\": 7500\n    }\n  ],\n  \"hours\": [\n    \"09:00\",\n    \"10:00\",\n    \"11:00\",\n    \"14:00\",\n    \"15:00\",\n    \"16:00\"\n  ],\n  \"sector\": \"sto\"\n}", "sto-booking/start.bat": "@echo off\ncd /d \"%~dp0\"\nset /p BOT_TOKEN=Telegram bot token (do not share): \npython bot.py\npause\n", "sto-booking/start.sh": "#!/usr/bin/env bash\ncd -- \"$(dirname -- \"$0\")\"\nread -r -s -p 'Telegram bot token (do not share): ' BOT_TOKEN\nprintf '\\n'\nexport BOT_TOKEN\npython3 bot.py\n", "sheets-crm/Code.gs": "/** BotStore CRM. Paste into Extensions > Apps Script in your own spreadsheet. */\nfunction onOpen() { SpreadsheetApp.getUi().createMenu('BotStore').addItem('Set up CRM', 'setupCRM').addToUi(); }\nfunction setupCRM() {\n const ss=SpreadsheetApp.getActive();\n let sheet=ss.getSheetByName('CRM');\n if(sheet && sheet.getLastRow()>0) {SpreadsheetApp.getUi().alert('CRM already contains data. Nothing changed.'); return;}\n sheet=sheet || ss.insertSheet('CRM');\n sheet.getRange('A1:G1').setValues([['Date / Күні / Дата','Client / Клиент','Phone / Телефон','Service / Қызмет / Услуга','Amount KZT / Сома / Сумма','Status / Статус','Notes / Ескерту / Заметки']]);\n sheet.getRange('A1:G1').setBackground('#5c50e8').setFontColor('#ffffff').setFontWeight('bold');\n sheet.setFrozenRows(1);sheet.getRange('C2:C1000').setNumberFormat('@');sheet.getRange('E2:E1000').setNumberFormat('#,##0 \"₸\"');\n const validation=SpreadsheetApp.newDataValidation().requireValueInList(['New','In progress','Paid','Cancelled'],true).setAllowInvalid(false).build();\n sheet.getRange('F2:F1000').setDataValidation(validation);sheet.autoResizeColumns(1,7);\n let summary=ss.getSheetByName('CRM Summary')||ss.insertSheet('CRM Summary');\n if(summary.getLastRow()===0){summary.getRange('A1:B3').setValues([['Metric','Value'],['Paid revenue','=SUMIF(CRM!F2:F1000,\"Paid\",CRM!E2:E1000)'],['Orders','=COUNTA(CRM!B2:B1000)']]);summary.autoResizeColumns(1,2);}\n SpreadsheetApp.getUi().alert('CRM ready / CRM дайын / CRM готова');\n}\n", "sheets-crm/README.md": "# BotStore\n\nLicense / Лицензия: MIT. You may use and modify this template commercially. Provided as-is without warranty.\n\nҚАЗАҚША\nФайлдарды жеке папкаға ашыңыз. Өз бизнесіңіздің деректерін енгізіп, алдымен сынақтан өткізіңіз. Құпия токендерді жарияламаңыз.\n\nРУССКИЙ\nРаспакуйте файлы в отдельную папку. Укажите данные своего бизнеса и протестируйте перед запуском. Не публикуйте секретные токены.\n\nENGLISH\nExtract to a folder, configure your business details and test before launch. Keep secret tokens private.\n\n## Google Sheets / Apps Script\n1. Create a new Google spreadsheet.\n2. Extensions → Apps Script. Replace the starter code with Code.gs. Save.\n3. Reload your spreadsheet. Open BotStore → Set up.\n4. Review Google permission request and authorize only your own copied script.\n5. Enter your records under the header. Summary recalculates automatically.\nҚАЗ: Жаңа Google кесте → Кеңейтімдер → Apps Script → Code.gs кодын салыңыз. Сақтап, кестені жаңартыңыз. BotStore мәзірінен іске қосыңыз.\nРУС: Новая таблица → Расширения → Apps Script → вставьте Code.gs. Сохраните, обновите таблицу, запустите настройку через меню BotStore.\nNo external API, payments, or bank integration. Formulas cover rows 2–1000; extend ranges if needed.\n", "business-website/README.md": "# BotStore\n\nLicense / Лицензия: MIT. You may use and modify this template commercially. Provided as-is without warranty.\n\nҚАЗАҚША\nФайлдарды жеке папкаға ашыңыз. Өз бизнесіңіздің деректерін енгізіп, алдымен сынақтан өткізіңіз. Құпия токендерді жарияламаңыз.\n\nРУССКИЙ\nРаспакуйте файлы в отдельную папку. Укажите данные своего бизнеса и протестируйте перед запуском. Не публикуйте секретные токены.\n\nENGLISH\nExtract to a folder, configure your business details and test before launch. Keep secret tokens private.\n\n## Website\nOpen index.html in a text editor. Edit config.name, config.phone (international format), config.address and config.services. Open in your browser to test. Upload index.html to any static hosting provider. The page supports kk/ru/en.\nҚАЗ: index.html ішіндегі config өрістерін өзгертіңіз. Браузерде тексеріп, хостингке жүктеңіз.\nРУС: Измените config внутри index.html, проверьте в браузере и загрузите на хостинг.\nHosting and domain are not included. WhatsApp must be available to your customers.\n", "business-website/index.html": "<!doctype html><html lang=\"kk\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>My Business</title><style>*{box-sizing:border-box}body{font:16px/1.7 system-ui;margin:0;color:#192441;background:#f8f9ff}header,main,footer{max-width:1000px;margin:auto;padding:30px}header{display:flex;justify-content:space-between}select{padding:8px;border-radius:6px;border:1px solid #ddd}section{padding:65px 0}h1{font-size:clamp(35px,6vw,64px);line-height:1.2;max-width:700px}h2{font-size:30px}.button{display:inline-block;background:#5c50e8;color:white;padding:14px 24px;border-radius:9px;text-decoration:none}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px}.card{padding:25px;background:white;border:1px solid #e5e6f0;border-radius:15px}.muted{color:#727b91}footer{border-top:1px solid #e5e6f0}</style><header><b id=\"brand\"></b><select id=\"lang\" aria-label=\"Language\"><option value=\"kk\">ҚАЗ</option><option value=\"ru\">РУС</option><option value=\"en\">ENG</option></select></header><main id=\"main\"></main><footer id=\"footer\"></footer><script>\n// EDIT your real business name, phone, address and prices below before publishing.\nconst config={name:'My Business',phone:'',address:'',services:[{kk:'Бірінші қызмет',ru:'Первая услуга',en:'First service',price:'5 000 ₸'},{kk:'Екінші қызмет',ru:'Вторая услуга',en:'Second service',price:'10 000 ₸'}]};\nconst texts={kk:['Сапалы қызмет. Жеке көзқарас.','Бізбен байланысып, өзіңізге ыңғайлы уақытты таңдаңыз.','Қызметтер','WhatsApp арқылы жазылу','Байланыс','Телефонды config ішінде енгізіңіз'],ru:['Качественный сервис. Личный подход.','Свяжитесь с нами и выберите удобное время.','Услуги','Записаться в WhatsApp','Контакты','Укажите телефон в config'],en:['Quality service. A personal touch.','Contact us to choose a time that works for you.','Services','Book via WhatsApp','Contact','Add your phone number in config']};\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction render(){const l=document.getElementById('lang').value,t=texts[l];document.documentElement.lang=l;document.title=config.name;document.getElementById('brand').textContent=config.name;const phone=config.phone.replace(/\\D/g,'');document.getElementById('main').innerHTML='<section><p class=\"muted\">'+esc(config.name)+'</p><h1>'+t[0]+'</h1><p class=\"muted\">'+t[1]+'</p>'+(phone?'<a class=\"button\" rel=\"noopener\" href=\"https://wa.me/'+phone+'\">'+t[3]+'</a>':'<p>'+t[5]+'</p>')+'</section><section><h2>'+t[2]+'</h2><div class=\"grid\">'+config.services.map(s=>'<article class=\"card\"><h3>'+esc(s[l])+'</h3><b>'+esc(s.price)+'</b></article>').join('')+'</div></section><section><h2>'+t[4]+'</h2><p>'+esc(config.phone)+'</p><p>'+esc(config.address)+'</p></section>';document.getElementById('footer').textContent='© '+new Date().getFullYear()+' '+config.name;}\ndocument.getElementById('lang').onchange=render;render();</script></html>\n", "START-HERE.md": "# BotStore · sto\n\n## Қазақша\nБұл пакетте үш бөлек құрал бар: `sto-booking`, `sheets-crm`, `business-website`.\nӘр қалтадағы README нұсқаулығын оқыңыз. Алдымен боттың баптауларын өзгертіп, тестілік тапсырысты өзіңіз тексеріңіз; кейін Google Sheets CRM мен сайтты орнатыңыз. Салон мен студия боты клиенттің аты мен телефонын сұрайды.\nPython 3.10+, Telegram бот токені және Google аккаунт қажет. Токенді жарияламаңыз. Бот компьютер/сервер қосулы кезде жұмыс істейді. Құралдар арасында автоматты синхрондау жоқ. Бағалар мен қызметтер — өзгертуге арналған мысалдар. Бір слотқа бір жазылу; UTC+5. Қызмет ұзақтығы және бірнеше қызметкердің кестесі автоматты есептелмейді. Хостинг, домен және орнату қызметі бөлек келісіледі.\n\n## Русский\nВ пакете три отдельных инструмента: `sto-booking`, `sheets-crm`, `business-website`.\nЧитайте README в каждой папке. Сначала настройте и проверьте бота тестовым заказом, затем установите CRM и сайт. Варианты для салона и студии спрашивают имя и телефон клиента.\nНужны Python 3.10+, токен Telegram-бота и Google-аккаунт. Не публикуйте токен. Бот работает, пока включён компьютер/сервер. Автоматической синхронизации нет. Услуги и цены — редактируемые примеры. Одна запись на слот; UTC+5. Длительности услуг и расписание нескольких сотрудников автоматически не рассчитываются. Хостинг, домен и помощь с установкой согласуются отдельно.\n\n## English\nThree separate tools: `sto-booking`, `sheets-crm`, `business-website`.\nRead the README in each folder. Configure and test the bot first, then set up the CRM and website. Salon and studio variants ask for the customer's name and phone.\nRequires Python 3.10+, a Telegram token and a Google account. Keep the token private. The bot needs a running computer/server. Tools do not sync automatically. Services and prices are editable examples. One appointment per slot; UTC+5. Service durations and multiple staff schedules are not calculated automatically. Hosting, domain and installation service are arranged separately.\n"}, "pack-salon": {"sto-booking/README.md": "# BotStore — Appointment Booking\n\nҚАЗАҚША\n1. Python 3.10+ орнатыңыз. ZIP архивін жеке папкаға ашыңыз.\n2. Telegram @BotFather арқылы жаңа бот ашыңыз.\n3. Windows: start.bat. macOS/Linux: bash start.sh. Токенді тек өз компьютеріңізде енгізіңіз.\n4. Ботқа /id жазыңыз. Өз нөміріңізді config.json ішіндегі adminChatId өрісіне немесе сайттағы орнату шеберіне қосыңыз. Қайта іске қосыңыз.\n5. Клиент /start → қызмет → күн → бос уақыт → аты мен телефон жазады. /my немесе /cancel арқылы жазылуды басқарады.\n6. Компьютер/сервер үнемі қосулы болуы керек. Хостинг және төлем қабылдау кірмейді. Бір слотқа бір клиент, уақыт белдеуі UTC+5. Алдағы 7 күн көрсетіледі. Қызметтер ұзақтығын слоттарды таңдағанда ескеріңіз.\n\nРУССКИЙ\n1. Установите Python 3.10+, распакуйте ZIP.\n2. Создайте нового бота через @BotFather.\n3. Запустите start.bat (Windows) или bash start.sh (macOS/Linux). Введите токен на своём компьютере. BotStore не сохраняет токен.\n4. Отправьте /id своему боту. Укажите полученный ID в adminChatId в config.json или мастере настройки, перезапустите.\n5. Клиент выбирает услугу, день и слот, вводит имя и телефон. /my и /cancel показывают записи и отмену. Одновременно слот бронируется только один раз.\n6. Компьютер или сервер должен работать постоянно. Хостинг и приём платежей не включены. Часовой пояс UTC+5, расписание на 7 дней, один клиент на слот. Задайте интервалы с учётом длительности работ.\n\nENGLISH\n1. Install Python 3.10+ and extract ZIP.\n2. Create a new bot with @BotFather.\n3. Run start.bat (Windows) or bash start.sh (macOS/Linux). Enter the token locally; BotStore never stores it.\n4. Send /id to your bot. Add the result as adminChatId in config.json or in the setup wizard. Restart.\n5. Customer flow: /start → service → day → available slot → name and phone. /my and /cancel allow viewing/cancelling bookings.\n6. An always-running computer/server is required. Hosting and payments are not included. UTC+5, next 7 days, one customer per slot. Space slots to accommodate your service duration.\n\nData is stored locally in bookings.sqlite3. Back up this file privately. Do not share it with customers or commit it to a public repository. Do not run two bot instances at once. MIT license; provided as-is without warranty.\n", "sto-booking/bot.py": "\"\"\"BotStore appointment bot. Python 3.10+. One booking per time slot, UTC+5.\"\"\"\nimport json,os,time,sqlite3,urllib.request,logging\nfrom datetime import datetime,timedelta,timezone\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parent\nCONFIG=json.loads((ROOT/'config.json').read_text(encoding='utf-8'))\nTOKEN=os.environ.get('BOT_TOKEN','')\nADMIN=CONFIG.get('adminChatId','')\nTZ=timezone(timedelta(hours=5))\nLANG=CONFIG.get('language','kk')\nTEXTS={\n'kk':dict(welcome='Сәлем! Қызметті таңдаңыз:',date='Күнді таңдаңыз:',time='Бос уақытты таңдаңыз:',phone='Көлік маркасын және байланыс телефоныңызды жазыңыз:',done='Жазылу расталды',busy='Бұл уақыт бос емес. /start арқылы басқа уақытты таңдаңыз.',invalid='Қайта бастау үшін /start басыңыз.',mine='Сіздің жазылуларыңыз:',cancel='Жазылуды болдырмау',cancelled='Жазылу тоқтатылды.',none='Белсенді жазылу жоқ.',contact='Телефон мен көлік туралы ақпаратты жазыңыз (8–150 таңба).'),\n'ru':dict(welcome='Здравствуйте! Выберите услугу:',date='Выберите день:',time='Выберите свободное время:',phone='Напишите марку машины и контактный телефон:',done='Запись подтверждена',busy='Это время уже занято. Выберите другое через /start.',invalid='Начните заново: /start',mine='Ваши записи:',cancel='Отменить запись',cancelled='Запись отменена.',none='Нет активных записей.',contact='Укажите телефон и автомобиль (8–150 символов).'),\n'en':dict(welcome='Welcome! Choose a service:',date='Choose a date:',time='Choose an available time:',phone='Send your vehicle model and contact phone number:',done='Booking confirmed',busy='This time is no longer available. Choose another with /start.',invalid='Start again: /start',mine='Your bookings:',cancel='Cancel booking',cancelled='Booking cancelled.',none='No active bookings.',contact='Enter a phone number and vehicle (8–150 characters).')}\nT=TEXTS.get(LANG,TEXTS['kk']).copy()\nif CONFIG.get('sector') in ('salon','studio'):\n T['phone']={'kk':'Атыңызды және байланыс телефоныңызды жазыңыз:','ru':'Напишите имя и контактный телефон:','en':'Send your name and contact phone number:'}.get(LANG,'Send your name and phone number:')\n T['contact']={'kk':'Атыңыз бен телефоныңызды жазыңыз (8–150 таңба).','ru':'Укажите имя и телефон (8–150 символов).','en':'Enter your name and phone (8–150 characters).'}.get(LANG,'Enter your name and phone.')\nDB=sqlite3.connect(ROOT/'bookings.sqlite3')\nDB.executescript('CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY,chat INTEGER NOT NULL,slot TEXT NOT NULL,service TEXT NOT NULL,contact TEXT NOT NULL,status TEXT NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS booked_slot ON bookings(slot) WHERE status=\"booked\"; CREATE TABLE IF NOT EXISTS sessions(chat INTEGER PRIMARY KEY,data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT);')\ndef api(method,data):\n req=urllib.request.Request('https://api.telegram.org/bot'+TOKEN+'/'+method,data=json.dumps(data).encode(),headers={'Content-Type':'application/json'})\n with urllib.request.urlopen(req,timeout=40) as r:res=json.load(r)\n if not res.get('ok'):raise RuntimeError('Telegram API error')\n return res['result']\ndef send(chat,text,buttons=None):\n data={'chat_id':chat,'text':text[:4000]}\n if buttons:data['reply_markup']={'inline_keyboard':buttons}\n return api('sendMessage',data)\ndef save(chat,data):\n DB.execute('INSERT INTO sessions(chat,data) VALUES(?,?) ON CONFLICT(chat) DO UPDATE SET data=excluded.data',(chat,json.dumps(data)));DB.commit()\ndef session(chat):\n row=DB.execute('SELECT data FROM sessions WHERE chat=?',(chat,)).fetchone();return json.loads(row[0]) if row else {}\ndef button(text,value):return {'text':text,'callback_data':value}\ndef start(chat):\n save(chat,{})\n send(chat,CONFIG['businessName']+'\\n'+T['welcome'],[[button(s['name']+' · '+str(s['price'])+' ₸','s:'+str(i))] for i,s in enumerate(CONFIG['services'])])\ndef mine(chat):\n rows=DB.execute('SELECT id,slot,service FROM bookings WHERE chat=? AND status=\"booked\" AND slot>? ORDER BY slot',(chat,datetime.now(TZ).strftime('%Y-%m-%d %H:%M'))).fetchall()\n if not rows:send(chat,T['none']);return\n for id,slot,service in rows:send(chat,service+'\\n'+slot,[[button(T['cancel'],'c:'+str(id))]])\ndef handle(update):\n q=update.get('callback_query')\n if q:\n  if q.get('message',{}).get('chat',{}).get('type')!='private':return\n  chat=q['from']['id'];value=q.get('data','');api('answerCallbackQuery',{'callback_query_id':q['id']});state=session(chat)\n  if value.startswith('c:'):\n   try:id=int(value[2:])\n   except ValueError:return\n   row=DB.execute('SELECT slot,service FROM bookings WHERE id=? AND chat=? AND status=\"booked\"',(id,chat)).fetchone()\n   DB.execute('UPDATE bookings SET status=\"cancelled\" WHERE id=? AND chat=?',(id,chat));DB.commit();send(chat,T['cancelled'])\n   if row and ADMIN:\n    try:send(ADMIN,'CANCELLED / ОТМЕНА / ТОҚТАТЫЛДЫ\\n'+row[0]+'\\n'+row[1])\n    except Exception:logging.warning('Admin notification failed')\n   return\n  if value.startswith('s:'):\n   try:i=int(value[2:])\n   except ValueError:return\n   if i<0 or i>=len(CONFIG['services']):return\n   save(chat,{'service':i});send(chat,T['date'],[[button((datetime.now(TZ)+timedelta(days=d)).strftime('%d.%m'), 'd:'+(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d'))] for d in range(7)]);return\n  if value.startswith('d:') and 'service' in state:\n   day=value[2:];allowed={(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d') for d in range(7)}\n   if day not in allowed:send(chat,T['invalid']);return\n   state['day']=day;state.pop('slot',None);save(chat,state);used={r[0] for r in DB.execute('SELECT slot FROM bookings WHERE status=\"booked\"').fetchall()};slots=[h for h in CONFIG['hours'] if day+' '+h not in used and day+' '+h>datetime.now(TZ).strftime('%Y-%m-%d %H:%M')]\n   send(chat,T['time'] if slots else T['busy'],[[button(h,'t:'+h)] for h in slots] if slots else None);return\n  if value.startswith('t:') and 'day' in state and 'service' in state:\n   hour=value[2:]\n   if hour not in CONFIG['hours']:return\n   state['slot']=state['day']+' '+hour;save(chat,state);send(chat,T['phone']);return\n  send(chat,T['invalid']);return\n msg=update.get('message',{})\n if msg.get('chat',{}).get('type')!='private':return\n chat=msg['chat']['id'];text=msg.get('text','').strip()\n if text=='/id':send(chat,str(chat));return\n if text.startswith('/start'):start(chat);return\n if text in ['/my','/cancel']:mine(chat);return\n state=session(chat)\n if 'slot' not in state:send(chat,T['invalid']);return\n if len(text)<8 or len(text)>150 or sum(c.isdigit() for c in text)<7:send(chat,T['contact']);return\n if state['slot']<=datetime.now(TZ).strftime('%Y-%m-%d %H:%M'):send(chat,T['busy']);return\n service=CONFIG['services'][state['service']];id=update['update_id']\n try:\n  DB.execute('INSERT INTO bookings(id,chat,slot,service,contact,status) VALUES(?,?,?,?,?,\"booked\")',(id,chat,state['slot'],service['name'],text));DB.commit()\n except sqlite3.IntegrityError:\n  existing=DB.execute('SELECT id FROM bookings WHERE id=? AND chat=?',(id,chat)).fetchone()\n  if not existing:send(chat,T['busy']);return\n save(chat,{})\n send(chat,T['done']+' ✓\\n'+service['name']+' · '+str(service['price'])+' ₸\\n'+state['slot']+' (UTC+5)',[[button(T['cancel'],'c:'+str(id))]])\n if ADMIN:\n  try:send(ADMIN,'NEW BOOKING / НОВАЯ ЗАПИСЬ / ЖАҢА ЖАЗЫЛУ\\n'+state['slot']+'\\n'+service['name']+'\\n'+text)\n  except Exception:logging.warning('Admin notification failed: check ADMIN chat has started the bot')\ndef main():\n if not TOKEN:raise SystemExit('Set BOT_TOKEN or use start.bat / start.sh')\n api('getMe',{});webhook=api('getWebhookInfo',{})\n if webhook.get('url'):raise SystemExit('This bot has a webhook. Use a new bot or remove the previous webhook intentionally before polling.')\n row=DB.execute('SELECT value FROM meta WHERE key=\"offset\"').fetchone();offset=int(row[0]) if row else 0\n print('BotStore booking bot running. Ctrl+C to stop.')\n while True:\n  try:\n   for update in api('getUpdates',{'offset':offset,'timeout':25,'allowed_updates':['message','callback_query']}):\n    try:handle(update)\n    except Exception:logging.warning('Update processing failed. Check connectivity and configuration.')\n    offset=update['update_id']+1;DB.execute('INSERT INTO meta(key,value) VALUES(\"offset\",?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(str(offset),));DB.commit()\n  except KeyboardInterrupt:break\n  except Exception:logging.warning('Connection unavailable, retrying');time.sleep(5)\nif __name__=='__main__':main()\n", "sto-booking/config.json": "{\n  \"businessName\": \"My Salon\",\n  \"language\": \"kk\",\n  \"adminChatId\": \"\",\n  \"services\": [\n    {\n      \"name\": \"Шаш қию / Стрижка / Haircut\",\n      \"price\": 5000\n    },\n    {\n      \"name\": \"Маникюр / Manicure\",\n      \"price\": 7000\n    }\n  ],\n  \"hours\": [\n    \"09:00\",\n    \"10:00\",\n    \"11:00\",\n    \"14:00\",\n    \"15:00\",\n    \"16:00\"\n  ],\n  \"sector\": \"salon\"\n}", "sto-booking/start.bat": "@echo off\ncd /d \"%~dp0\"\nset /p BOT_TOKEN=Telegram bot token (do not share): \npython bot.py\npause\n", "sto-booking/start.sh": "#!/usr/bin/env bash\ncd -- \"$(dirname -- \"$0\")\"\nread -r -s -p 'Telegram bot token (do not share): ' BOT_TOKEN\nprintf '\\n'\nexport BOT_TOKEN\npython3 bot.py\n", "sheets-crm/Code.gs": "/** BotStore CRM. Paste into Extensions > Apps Script in your own spreadsheet. */\nfunction onOpen() { SpreadsheetApp.getUi().createMenu('BotStore').addItem('Set up CRM', 'setupCRM').addToUi(); }\nfunction setupCRM() {\n const ss=SpreadsheetApp.getActive();\n let sheet=ss.getSheetByName('CRM');\n if(sheet && sheet.getLastRow()>0) {SpreadsheetApp.getUi().alert('CRM already contains data. Nothing changed.'); return;}\n sheet=sheet || ss.insertSheet('CRM');\n sheet.getRange('A1:G1').setValues([['Date / Күні / Дата','Client / Клиент','Phone / Телефон','Service / Қызмет / Услуга','Amount KZT / Сома / Сумма','Status / Статус','Notes / Ескерту / Заметки']]);\n sheet.getRange('A1:G1').setBackground('#5c50e8').setFontColor('#ffffff').setFontWeight('bold');\n sheet.setFrozenRows(1);sheet.getRange('C2:C1000').setNumberFormat('@');sheet.getRange('E2:E1000').setNumberFormat('#,##0 \"₸\"');\n const validation=SpreadsheetApp.newDataValidation().requireValueInList(['New','In progress','Paid','Cancelled'],true).setAllowInvalid(false).build();\n sheet.getRange('F2:F1000').setDataValidation(validation);sheet.autoResizeColumns(1,7);\n let summary=ss.getSheetByName('CRM Summary')||ss.insertSheet('CRM Summary');\n if(summary.getLastRow()===0){summary.getRange('A1:B3').setValues([['Metric','Value'],['Paid revenue','=SUMIF(CRM!F2:F1000,\"Paid\",CRM!E2:E1000)'],['Orders','=COUNTA(CRM!B2:B1000)']]);summary.autoResizeColumns(1,2);}\n SpreadsheetApp.getUi().alert('CRM ready / CRM дайын / CRM готова');\n}\n", "sheets-crm/README.md": "# BotStore\n\nLicense / Лицензия: MIT. You may use and modify this template commercially. Provided as-is without warranty.\n\nҚАЗАҚША\nФайлдарды жеке папкаға ашыңыз. Өз бизнесіңіздің деректерін енгізіп, алдымен сынақтан өткізіңіз. Құпия токендерді жарияламаңыз.\n\nРУССКИЙ\nРаспакуйте файлы в отдельную папку. Укажите данные своего бизнеса и протестируйте перед запуском. Не публикуйте секретные токены.\n\nENGLISH\nExtract to a folder, configure your business details and test before launch. Keep secret tokens private.\n\n## Google Sheets / Apps Script\n1. Create a new Google spreadsheet.\n2. Extensions → Apps Script. Replace the starter code with Code.gs. Save.\n3. Reload your spreadsheet. Open BotStore → Set up.\n4. Review Google permission request and authorize only your own copied script.\n5. Enter your records under the header. Summary recalculates automatically.\nҚАЗ: Жаңа Google кесте → Кеңейтімдер → Apps Script → Code.gs кодын салыңыз. Сақтап, кестені жаңартыңыз. BotStore мәзірінен іске қосыңыз.\nРУС: Новая таблица → Расширения → Apps Script → вставьте Code.gs. Сохраните, обновите таблицу, запустите настройку через меню BotStore.\nNo external API, payments, or bank integration. Formulas cover rows 2–1000; extend ranges if needed.\n", "business-website/README.md": "# BotStore\n\nLicense / Лицензия: MIT. You may use and modify this template commercially. Provided as-is without warranty.\n\nҚАЗАҚША\nФайлдарды жеке папкаға ашыңыз. Өз бизнесіңіздің деректерін енгізіп, алдымен сынақтан өткізіңіз. Құпия токендерді жарияламаңыз.\n\nРУССКИЙ\nРаспакуйте файлы в отдельную папку. Укажите данные своего бизнеса и протестируйте перед запуском. Не публикуйте секретные токены.\n\nENGLISH\nExtract to a folder, configure your business details and test before launch. Keep secret tokens private.\n\n## Website\nOpen index.html in a text editor. Edit config.name, config.phone (international format), config.address and config.services. Open in your browser to test. Upload index.html to any static hosting provider. The page supports kk/ru/en.\nҚАЗ: index.html ішіндегі config өрістерін өзгертіңіз. Браузерде тексеріп, хостингке жүктеңіз.\nРУС: Измените config внутри index.html, проверьте в браузере и загрузите на хостинг.\nHosting and domain are not included. WhatsApp must be available to your customers.\n", "business-website/index.html": "<!doctype html><html lang=\"kk\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>My Business</title><style>*{box-sizing:border-box}body{font:16px/1.7 system-ui;margin:0;color:#192441;background:#f8f9ff}header,main,footer{max-width:1000px;margin:auto;padding:30px}header{display:flex;justify-content:space-between}select{padding:8px;border-radius:6px;border:1px solid #ddd}section{padding:65px 0}h1{font-size:clamp(35px,6vw,64px);line-height:1.2;max-width:700px}h2{font-size:30px}.button{display:inline-block;background:#5c50e8;color:white;padding:14px 24px;border-radius:9px;text-decoration:none}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px}.card{padding:25px;background:white;border:1px solid #e5e6f0;border-radius:15px}.muted{color:#727b91}footer{border-top:1px solid #e5e6f0}</style><header><b id=\"brand\"></b><select id=\"lang\" aria-label=\"Language\"><option value=\"kk\">ҚАЗ</option><option value=\"ru\">РУС</option><option value=\"en\">ENG</option></select></header><main id=\"main\"></main><footer id=\"footer\"></footer><script>\n// EDIT your real business name, phone, address and prices below before publishing.\nconst config={name:'My Business',phone:'',address:'',services:[{kk:'Бірінші қызмет',ru:'Первая услуга',en:'First service',price:'5 000 ₸'},{kk:'Екінші қызмет',ru:'Вторая услуга',en:'Second service',price:'10 000 ₸'}]};\nconst texts={kk:['Сапалы қызмет. Жеке көзқарас.','Бізбен байланысып, өзіңізге ыңғайлы уақытты таңдаңыз.','Қызметтер','WhatsApp арқылы жазылу','Байланыс','Телефонды config ішінде енгізіңіз'],ru:['Качественный сервис. Личный подход.','Свяжитесь с нами и выберите удобное время.','Услуги','Записаться в WhatsApp','Контакты','Укажите телефон в config'],en:['Quality service. A personal touch.','Contact us to choose a time that works for you.','Services','Book via WhatsApp','Contact','Add your phone number in config']};\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction render(){const l=document.getElementById('lang').value,t=texts[l];document.documentElement.lang=l;document.title=config.name;document.getElementById('brand').textContent=config.name;const phone=config.phone.replace(/\\D/g,'');document.getElementById('main').innerHTML='<section><p class=\"muted\">'+esc(config.name)+'</p><h1>'+t[0]+'</h1><p class=\"muted\">'+t[1]+'</p>'+(phone?'<a class=\"button\" rel=\"noopener\" href=\"https://wa.me/'+phone+'\">'+t[3]+'</a>':'<p>'+t[5]+'</p>')+'</section><section><h2>'+t[2]+'</h2><div class=\"grid\">'+config.services.map(s=>'<article class=\"card\"><h3>'+esc(s[l])+'</h3><b>'+esc(s.price)+'</b></article>').join('')+'</div></section><section><h2>'+t[4]+'</h2><p>'+esc(config.phone)+'</p><p>'+esc(config.address)+'</p></section>';document.getElementById('footer').textContent='© '+new Date().getFullYear()+' '+config.name;}\ndocument.getElementById('lang').onchange=render;render();</script></html>\n", "START-HERE.md": "# BotStore · salon\n\n## Қазақша\nБұл пакетте үш бөлек құрал бар: `sto-booking`, `sheets-crm`, `business-website`.\nӘр қалтадағы README нұсқаулығын оқыңыз. Алдымен боттың баптауларын өзгертіп, тестілік тапсырысты өзіңіз тексеріңіз; кейін Google Sheets CRM мен сайтты орнатыңыз. Салон мен студия боты клиенттің аты мен телефонын сұрайды.\nPython 3.10+, Telegram бот токені және Google аккаунт қажет. Токенді жарияламаңыз. Бот компьютер/сервер қосулы кезде жұмыс істейді. Құралдар арасында автоматты синхрондау жоқ. Бағалар мен қызметтер — өзгертуге арналған мысалдар. Бір слотқа бір жазылу; UTC+5. Қызмет ұзақтығы және бірнеше қызметкердің кестесі автоматты есептелмейді. Хостинг, домен және орнату қызметі бөлек келісіледі.\n\n## Русский\nВ пакете три отдельных инструмента: `sto-booking`, `sheets-crm`, `business-website`.\nЧитайте README в каждой папке. Сначала настройте и проверьте бота тестовым заказом, затем установите CRM и сайт. Варианты для салона и студии спрашивают имя и телефон клиента.\nНужны Python 3.10+, токен Telegram-бота и Google-аккаунт. Не публикуйте токен. Бот работает, пока включён компьютер/сервер. Автоматической синхронизации нет. Услуги и цены — редактируемые примеры. Одна запись на слот; UTC+5. Длительности услуг и расписание нескольких сотрудников автоматически не рассчитываются. Хостинг, домен и помощь с установкой согласуются отдельно.\n\n## English\nThree separate tools: `sto-booking`, `sheets-crm`, `business-website`.\nRead the README in each folder. Configure and test the bot first, then set up the CRM and website. Salon and studio variants ask for the customer's name and phone.\nRequires Python 3.10+, a Telegram token and a Google account. Keep the token private. The bot needs a running computer/server. Tools do not sync automatically. Services and prices are editable examples. One appointment per slot; UTC+5. Service durations and multiple staff schedules are not calculated automatically. Hosting, domain and installation service are arranged separately.\n"}, "pack-studio": {"sto-booking/README.md": "# BotStore — Appointment Booking\n\nҚАЗАҚША\n1. Python 3.10+ орнатыңыз. ZIP архивін жеке папкаға ашыңыз.\n2. Telegram @BotFather арқылы жаңа бот ашыңыз.\n3. Windows: start.bat. macOS/Linux: bash start.sh. Токенді тек өз компьютеріңізде енгізіңіз.\n4. Ботқа /id жазыңыз. Өз нөміріңізді config.json ішіндегі adminChatId өрісіне немесе сайттағы орнату шеберіне қосыңыз. Қайта іске қосыңыз.\n5. Клиент /start → қызмет → күн → бос уақыт → аты мен телефон жазады. /my немесе /cancel арқылы жазылуды басқарады.\n6. Компьютер/сервер үнемі қосулы болуы керек. Хостинг және төлем қабылдау кірмейді. Бір слотқа бір клиент, уақыт белдеуі UTC+5. Алдағы 7 күн көрсетіледі. Қызметтер ұзақтығын слоттарды таңдағанда ескеріңіз.\n\nРУССКИЙ\n1. Установите Python 3.10+, распакуйте ZIP.\n2. Создайте нового бота через @BotFather.\n3. Запустите start.bat (Windows) или bash start.sh (macOS/Linux). Введите токен на своём компьютере. BotStore не сохраняет токен.\n4. Отправьте /id своему боту. Укажите полученный ID в adminChatId в config.json или мастере настройки, перезапустите.\n5. Клиент выбирает услугу, день и слот, вводит имя и телефон. /my и /cancel показывают записи и отмену. Одновременно слот бронируется только один раз.\n6. Компьютер или сервер должен работать постоянно. Хостинг и приём платежей не включены. Часовой пояс UTC+5, расписание на 7 дней, один клиент на слот. Задайте интервалы с учётом длительности работ.\n\nENGLISH\n1. Install Python 3.10+ and extract ZIP.\n2. Create a new bot with @BotFather.\n3. Run start.bat (Windows) or bash start.sh (macOS/Linux). Enter the token locally; BotStore never stores it.\n4. Send /id to your bot. Add the result as adminChatId in config.json or in the setup wizard. Restart.\n5. Customer flow: /start → service → day → available slot → name and phone. /my and /cancel allow viewing/cancelling bookings.\n6. An always-running computer/server is required. Hosting and payments are not included. UTC+5, next 7 days, one customer per slot. Space slots to accommodate your service duration.\n\nData is stored locally in bookings.sqlite3. Back up this file privately. Do not share it with customers or commit it to a public repository. Do not run two bot instances at once. MIT license; provided as-is without warranty.\n", "sto-booking/bot.py": "\"\"\"BotStore appointment bot. Python 3.10+. One booking per time slot, UTC+5.\"\"\"\nimport json,os,time,sqlite3,urllib.request,logging\nfrom datetime import datetime,timedelta,timezone\nfrom pathlib import Path\nROOT=Path(__file__).resolve().parent\nCONFIG=json.loads((ROOT/'config.json').read_text(encoding='utf-8'))\nTOKEN=os.environ.get('BOT_TOKEN','')\nADMIN=CONFIG.get('adminChatId','')\nTZ=timezone(timedelta(hours=5))\nLANG=CONFIG.get('language','kk')\nTEXTS={\n'kk':dict(welcome='Сәлем! Қызметті таңдаңыз:',date='Күнді таңдаңыз:',time='Бос уақытты таңдаңыз:',phone='Көлік маркасын және байланыс телефоныңызды жазыңыз:',done='Жазылу расталды',busy='Бұл уақыт бос емес. /start арқылы басқа уақытты таңдаңыз.',invalid='Қайта бастау үшін /start басыңыз.',mine='Сіздің жазылуларыңыз:',cancel='Жазылуды болдырмау',cancelled='Жазылу тоқтатылды.',none='Белсенді жазылу жоқ.',contact='Телефон мен көлік туралы ақпаратты жазыңыз (8–150 таңба).'),\n'ru':dict(welcome='Здравствуйте! Выберите услугу:',date='Выберите день:',time='Выберите свободное время:',phone='Напишите марку машины и контактный телефон:',done='Запись подтверждена',busy='Это время уже занято. Выберите другое через /start.',invalid='Начните заново: /start',mine='Ваши записи:',cancel='Отменить запись',cancelled='Запись отменена.',none='Нет активных записей.',contact='Укажите телефон и автомобиль (8–150 символов).'),\n'en':dict(welcome='Welcome! Choose a service:',date='Choose a date:',time='Choose an available time:',phone='Send your vehicle model and contact phone number:',done='Booking confirmed',busy='This time is no longer available. Choose another with /start.',invalid='Start again: /start',mine='Your bookings:',cancel='Cancel booking',cancelled='Booking cancelled.',none='No active bookings.',contact='Enter a phone number and vehicle (8–150 characters).')}\nT=TEXTS.get(LANG,TEXTS['kk']).copy()\nif CONFIG.get('sector') in ('salon','studio'):\n T['phone']={'kk':'Атыңызды және байланыс телефоныңызды жазыңыз:','ru':'Напишите имя и контактный телефон:','en':'Send your name and contact phone number:'}.get(LANG,'Send your name and phone number:')\n T['contact']={'kk':'Атыңыз бен телефоныңызды жазыңыз (8–150 таңба).','ru':'Укажите имя и телефон (8–150 символов).','en':'Enter your name and phone (8–150 characters).'}.get(LANG,'Enter your name and phone.')\nDB=sqlite3.connect(ROOT/'bookings.sqlite3')\nDB.executescript('CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY,chat INTEGER NOT NULL,slot TEXT NOT NULL,service TEXT NOT NULL,contact TEXT NOT NULL,status TEXT NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS booked_slot ON bookings(slot) WHERE status=\"booked\"; CREATE TABLE IF NOT EXISTS sessions(chat INTEGER PRIMARY KEY,data TEXT NOT NULL); CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT);')\ndef api(method,data):\n req=urllib.request.Request('https://api.telegram.org/bot'+TOKEN+'/'+method,data=json.dumps(data).encode(),headers={'Content-Type':'application/json'})\n with urllib.request.urlopen(req,timeout=40) as r:res=json.load(r)\n if not res.get('ok'):raise RuntimeError('Telegram API error')\n return res['result']\ndef send(chat,text,buttons=None):\n data={'chat_id':chat,'text':text[:4000]}\n if buttons:data['reply_markup']={'inline_keyboard':buttons}\n return api('sendMessage',data)\ndef save(chat,data):\n DB.execute('INSERT INTO sessions(chat,data) VALUES(?,?) ON CONFLICT(chat) DO UPDATE SET data=excluded.data',(chat,json.dumps(data)));DB.commit()\ndef session(chat):\n row=DB.execute('SELECT data FROM sessions WHERE chat=?',(chat,)).fetchone();return json.loads(row[0]) if row else {}\ndef button(text,value):return {'text':text,'callback_data':value}\ndef start(chat):\n save(chat,{})\n send(chat,CONFIG['businessName']+'\\n'+T['welcome'],[[button(s['name']+' · '+str(s['price'])+' ₸','s:'+str(i))] for i,s in enumerate(CONFIG['services'])])\ndef mine(chat):\n rows=DB.execute('SELECT id,slot,service FROM bookings WHERE chat=? AND status=\"booked\" AND slot>? ORDER BY slot',(chat,datetime.now(TZ).strftime('%Y-%m-%d %H:%M'))).fetchall()\n if not rows:send(chat,T['none']);return\n for id,slot,service in rows:send(chat,service+'\\n'+slot,[[button(T['cancel'],'c:'+str(id))]])\ndef handle(update):\n q=update.get('callback_query')\n if q:\n  if q.get('message',{}).get('chat',{}).get('type')!='private':return\n  chat=q['from']['id'];value=q.get('data','');api('answerCallbackQuery',{'callback_query_id':q['id']});state=session(chat)\n  if value.startswith('c:'):\n   try:id=int(value[2:])\n   except ValueError:return\n   row=DB.execute('SELECT slot,service FROM bookings WHERE id=? AND chat=? AND status=\"booked\"',(id,chat)).fetchone()\n   DB.execute('UPDATE bookings SET status=\"cancelled\" WHERE id=? AND chat=?',(id,chat));DB.commit();send(chat,T['cancelled'])\n   if row and ADMIN:\n    try:send(ADMIN,'CANCELLED / ОТМЕНА / ТОҚТАТЫЛДЫ\\n'+row[0]+'\\n'+row[1])\n    except Exception:logging.warning('Admin notification failed')\n   return\n  if value.startswith('s:'):\n   try:i=int(value[2:])\n   except ValueError:return\n   if i<0 or i>=len(CONFIG['services']):return\n   save(chat,{'service':i});send(chat,T['date'],[[button((datetime.now(TZ)+timedelta(days=d)).strftime('%d.%m'), 'd:'+(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d'))] for d in range(7)]);return\n  if value.startswith('d:') and 'service' in state:\n   day=value[2:];allowed={(datetime.now(TZ)+timedelta(days=d)).strftime('%Y-%m-%d') for d in range(7)}\n   if day not in allowed:send(chat,T['invalid']);return\n   state['day']=day;state.pop('slot',None);save(chat,state);used={r[0] for r in DB.execute('SELECT slot FROM bookings WHERE status=\"booked\"').fetchall()};slots=[h for h in CONFIG['hours'] if day+' '+h not in used and day+' '+h>datetime.now(TZ).strftime('%Y-%m-%d %H:%M')]\n   send(chat,T['time'] if slots else T['busy'],[[button(h,'t:'+h)] for h in slots] if slots else None);return\n  if value.startswith('t:') and 'day' in state and 'service' in state:\n   hour=value[2:]\n   if hour not in CONFIG['hours']:return\n   state['slot']=state['day']+' '+hour;save(chat,state);send(chat,T['phone']);return\n  send(chat,T['invalid']);return\n msg=update.get('message',{})\n if msg.get('chat',{}).get('type')!='private':return\n chat=msg['chat']['id'];text=msg.get('text','').strip()\n if text=='/id':send(chat,str(chat));return\n if text.startswith('/start'):start(chat);return\n if text in ['/my','/cancel']:mine(chat);return\n state=session(chat)\n if 'slot' not in state:send(chat,T['invalid']);return\n if len(text)<8 or len(text)>150 or sum(c.isdigit() for c in text)<7:send(chat,T['contact']);return\n if state['slot']<=datetime.now(TZ).strftime('%Y-%m-%d %H:%M'):send(chat,T['busy']);return\n service=CONFIG['services'][state['service']];id=update['update_id']\n try:\n  DB.execute('INSERT INTO bookings(id,chat,slot,service,contact,status) VALUES(?,?,?,?,?,\"booked\")',(id,chat,state['slot'],service['name'],text));DB.commit()\n except sqlite3.IntegrityError:\n  existing=DB.execute('SELECT id FROM bookings WHERE id=? AND chat=?',(id,chat)).fetchone()\n  if not existing:send(chat,T['busy']);return\n save(chat,{})\n send(chat,T['done']+' ✓\\n'+service['name']+' · '+str(service['price'])+' ₸\\n'+state['slot']+' (UTC+5)',[[button(T['cancel'],'c:'+str(id))]])\n if ADMIN:\n  try:send(ADMIN,'NEW BOOKING / НОВАЯ ЗАПИСЬ / ЖАҢА ЖАЗЫЛУ\\n'+state['slot']+'\\n'+service['name']+'\\n'+text)\n  except Exception:logging.warning('Admin notification failed: check ADMIN chat has started the bot')\ndef main():\n if not TOKEN:raise SystemExit('Set BOT_TOKEN or use start.bat / start.sh')\n api('getMe',{});webhook=api('getWebhookInfo',{})\n if webhook.get('url'):raise SystemExit('This bot has a webhook. Use a new bot or remove the previous webhook intentionally before polling.')\n row=DB.execute('SELECT value FROM meta WHERE key=\"offset\"').fetchone();offset=int(row[0]) if row else 0\n print('BotStore booking bot running. Ctrl+C to stop.')\n while True:\n  try:\n   for update in api('getUpdates',{'offset':offset,'timeout':25,'allowed_updates':['message','callback_query']}):\n    try:handle(update)\n    except Exception:logging.warning('Update processing failed. Check connectivity and configuration.')\n    offset=update['update_id']+1;DB.execute('INSERT INTO meta(key,value) VALUES(\"offset\",?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',(str(offset),));DB.commit()\n  except KeyboardInterrupt:break\n  except Exception:logging.warning('Connection unavailable, retrying');time.sleep(5)\nif __name__=='__main__':main()\n", "sto-booking/config.json": "{\n  \"businessName\": \"My Studio\",\n  \"language\": \"kk\",\n  \"adminChatId\": \"\",\n  \"services\": [\n    {\n      \"name\": \"Фотосессия / Photo session\",\n      \"price\": 15000\n    }\n  ],\n  \"hours\": [\n    \"09:00\",\n    \"11:00\",\n    \"14:00\",\n    \"16:00\"\n  ],\n  \"sector\": \"studio\"\n}", "sto-booking/start.bat": "@echo off\ncd /d \"%~dp0\"\nset /p BOT_TOKEN=Telegram bot token (do not share): \npython bot.py\npause\n", "sto-booking/start.sh": "#!/usr/bin/env bash\ncd -- \"$(dirname -- \"$0\")\"\nread -r -s -p 'Telegram bot token (do not share): ' BOT_TOKEN\nprintf '\\n'\nexport BOT_TOKEN\npython3 bot.py\n", "sheets-crm/Code.gs": "/** BotStore CRM. Paste into Extensions > Apps Script in your own spreadsheet. */\nfunction onOpen() { SpreadsheetApp.getUi().createMenu('BotStore').addItem('Set up CRM', 'setupCRM').addToUi(); }\nfunction setupCRM() {\n const ss=SpreadsheetApp.getActive();\n let sheet=ss.getSheetByName('CRM');\n if(sheet && sheet.getLastRow()>0) {SpreadsheetApp.getUi().alert('CRM already contains data. Nothing changed.'); return;}\n sheet=sheet || ss.insertSheet('CRM');\n sheet.getRange('A1:G1').setValues([['Date / Күні / Дата','Client / Клиент','Phone / Телефон','Service / Қызмет / Услуга','Amount KZT / Сома / Сумма','Status / Статус','Notes / Ескерту / Заметки']]);\n sheet.getRange('A1:G1').setBackground('#5c50e8').setFontColor('#ffffff').setFontWeight('bold');\n sheet.setFrozenRows(1);sheet.getRange('C2:C1000').setNumberFormat('@');sheet.getRange('E2:E1000').setNumberFormat('#,##0 \"₸\"');\n const validation=SpreadsheetApp.newDataValidation().requireValueInList(['New','In progress','Paid','Cancelled'],true).setAllowInvalid(false).build();\n sheet.getRange('F2:F1000').setDataValidation(validation);sheet.autoResizeColumns(1,7);\n let summary=ss.getSheetByName('CRM Summary')||ss.insertSheet('CRM Summary');\n if(summary.getLastRow()===0){summary.getRange('A1:B3').setValues([['Metric','Value'],['Paid revenue','=SUMIF(CRM!F2:F1000,\"Paid\",CRM!E2:E1000)'],['Orders','=COUNTA(CRM!B2:B1000)']]);summary.autoResizeColumns(1,2);}\n SpreadsheetApp.getUi().alert('CRM ready / CRM дайын / CRM готова');\n}\n", "sheets-crm/README.md": "# BotStore\n\nLicense / Лицензия: MIT. You may use and modify this template commercially. Provided as-is without warranty.\n\nҚАЗАҚША\nФайлдарды жеке папкаға ашыңыз. Өз бизнесіңіздің деректерін енгізіп, алдымен сынақтан өткізіңіз. Құпия токендерді жарияламаңыз.\n\nРУССКИЙ\nРаспакуйте файлы в отдельную папку. Укажите данные своего бизнеса и протестируйте перед запуском. Не публикуйте секретные токены.\n\nENGLISH\nExtract to a folder, configure your business details and test before launch. Keep secret tokens private.\n\n## Google Sheets / Apps Script\n1. Create a new Google spreadsheet.\n2. Extensions → Apps Script. Replace the starter code with Code.gs. Save.\n3. Reload your spreadsheet. Open BotStore → Set up.\n4. Review Google permission request and authorize only your own copied script.\n5. Enter your records under the header. Summary recalculates automatically.\nҚАЗ: Жаңа Google кесте → Кеңейтімдер → Apps Script → Code.gs кодын салыңыз. Сақтап, кестені жаңартыңыз. BotStore мәзірінен іске қосыңыз.\nРУС: Новая таблица → Расширения → Apps Script → вставьте Code.gs. Сохраните, обновите таблицу, запустите настройку через меню BotStore.\nNo external API, payments, or bank integration. Formulas cover rows 2–1000; extend ranges if needed.\n", "business-website/README.md": "# BotStore\n\nLicense / Лицензия: MIT. You may use and modify this template commercially. Provided as-is without warranty.\n\nҚАЗАҚША\nФайлдарды жеке папкаға ашыңыз. Өз бизнесіңіздің деректерін енгізіп, алдымен сынақтан өткізіңіз. Құпия токендерді жарияламаңыз.\n\nРУССКИЙ\nРаспакуйте файлы в отдельную папку. Укажите данные своего бизнеса и протестируйте перед запуском. Не публикуйте секретные токены.\n\nENGLISH\nExtract to a folder, configure your business details and test before launch. Keep secret tokens private.\n\n## Website\nOpen index.html in a text editor. Edit config.name, config.phone (international format), config.address and config.services. Open in your browser to test. Upload index.html to any static hosting provider. The page supports kk/ru/en.\nҚАЗ: index.html ішіндегі config өрістерін өзгертіңіз. Браузерде тексеріп, хостингке жүктеңіз.\nРУС: Измените config внутри index.html, проверьте в браузере и загрузите на хостинг.\nHosting and domain are not included. WhatsApp must be available to your customers.\n", "business-website/index.html": "<!doctype html><html lang=\"kk\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>My Business</title><style>*{box-sizing:border-box}body{font:16px/1.7 system-ui;margin:0;color:#192441;background:#f8f9ff}header,main,footer{max-width:1000px;margin:auto;padding:30px}header{display:flex;justify-content:space-between}select{padding:8px;border-radius:6px;border:1px solid #ddd}section{padding:65px 0}h1{font-size:clamp(35px,6vw,64px);line-height:1.2;max-width:700px}h2{font-size:30px}.button{display:inline-block;background:#5c50e8;color:white;padding:14px 24px;border-radius:9px;text-decoration:none}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px}.card{padding:25px;background:white;border:1px solid #e5e6f0;border-radius:15px}.muted{color:#727b91}footer{border-top:1px solid #e5e6f0}</style><header><b id=\"brand\"></b><select id=\"lang\" aria-label=\"Language\"><option value=\"kk\">ҚАЗ</option><option value=\"ru\">РУС</option><option value=\"en\">ENG</option></select></header><main id=\"main\"></main><footer id=\"footer\"></footer><script>\n// EDIT your real business name, phone, address and prices below before publishing.\nconst config={name:'My Business',phone:'',address:'',services:[{kk:'Бірінші қызмет',ru:'Первая услуга',en:'First service',price:'5 000 ₸'},{kk:'Екінші қызмет',ru:'Вторая услуга',en:'Second service',price:'10 000 ₸'}]};\nconst texts={kk:['Сапалы қызмет. Жеке көзқарас.','Бізбен байланысып, өзіңізге ыңғайлы уақытты таңдаңыз.','Қызметтер','WhatsApp арқылы жазылу','Байланыс','Телефонды config ішінде енгізіңіз'],ru:['Качественный сервис. Личный подход.','Свяжитесь с нами и выберите удобное время.','Услуги','Записаться в WhatsApp','Контакты','Укажите телефон в config'],en:['Quality service. A personal touch.','Contact us to choose a time that works for you.','Services','Book via WhatsApp','Contact','Add your phone number in config']};\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction render(){const l=document.getElementById('lang').value,t=texts[l];document.documentElement.lang=l;document.title=config.name;document.getElementById('brand').textContent=config.name;const phone=config.phone.replace(/\\D/g,'');document.getElementById('main').innerHTML='<section><p class=\"muted\">'+esc(config.name)+'</p><h1>'+t[0]+'</h1><p class=\"muted\">'+t[1]+'</p>'+(phone?'<a class=\"button\" rel=\"noopener\" href=\"https://wa.me/'+phone+'\">'+t[3]+'</a>':'<p>'+t[5]+'</p>')+'</section><section><h2>'+t[2]+'</h2><div class=\"grid\">'+config.services.map(s=>'<article class=\"card\"><h3>'+esc(s[l])+'</h3><b>'+esc(s.price)+'</b></article>').join('')+'</div></section><section><h2>'+t[4]+'</h2><p>'+esc(config.phone)+'</p><p>'+esc(config.address)+'</p></section>';document.getElementById('footer').textContent='© '+new Date().getFullYear()+' '+config.name;}\ndocument.getElementById('lang').onchange=render;render();</script></html>\n", "START-HERE.md": "# BotStore · studio\n\n## Қазақша\nБұл пакетте үш бөлек құрал бар: `sto-booking`, `sheets-crm`, `business-website`.\nӘр қалтадағы README нұсқаулығын оқыңыз. Алдымен боттың баптауларын өзгертіп, тестілік тапсырысты өзіңіз тексеріңіз; кейін Google Sheets CRM мен сайтты орнатыңыз. Салон мен студия боты клиенттің аты мен телефонын сұрайды.\nPython 3.10+, Telegram бот токені және Google аккаунт қажет. Токенді жарияламаңыз. Бот компьютер/сервер қосулы кезде жұмыс істейді. Құралдар арасында автоматты синхрондау жоқ. Бағалар мен қызметтер — өзгертуге арналған мысалдар. Бір слотқа бір жазылу; UTC+5. Қызмет ұзақтығы және бірнеше қызметкердің кестесі автоматты есептелмейді. Хостинг, домен және орнату қызметі бөлек келісіледі.\n\n## Русский\nВ пакете три отдельных инструмента: `sto-booking`, `sheets-crm`, `business-website`.\nЧитайте README в каждой папке. Сначала настройте и проверьте бота тестовым заказом, затем установите CRM и сайт. Варианты для салона и студии спрашивают имя и телефон клиента.\nНужны Python 3.10+, токен Telegram-бота и Google-аккаунт. Не публикуйте токен. Бот работает, пока включён компьютер/сервер. Автоматической синхронизации нет. Услуги и цены — редактируемые примеры. Одна запись на слот; UTC+5. Длительности услуг и расписание нескольких сотрудников автоматически не рассчитываются. Хостинг, домен и помощь с установкой согласуются отдельно.\n\n## English\nThree separate tools: `sto-booking`, `sheets-crm`, `business-website`.\nRead the README in each folder. Configure and test the bot first, then set up the CRM and website. Salon and studio variants ask for the customer's name and phone.\nRequires Python 3.10+, a Telegram token and a Google account. Keep the token private. The bot needs a running computer/server. Tools do not sync automatically. Services and prices are editable examples. One appointment per slot; UTC+5. Service durations and multiple staff schedules are not calculated automatically. Hosting, domain and installation service are arranged separately.\n"}};
